// Some portions generated by Claude
import { instance, type Viz } from '@viz-js/viz';
import { graphNodeSize } from './graph-geometry.ts';
import {LAYOUT_SPACING as gap} from './graph-layout-spacing.ts';
import type { Graph, PointerPosition } from './graph-types.ts';

let runtime: Promise<Viz> | undefined;

/** WASM is bundled with the worker: layout works offline and sends no RDF out. */
export async function computeGraphvizLayout(graph: Graph, engine = 'sfdp', attributes: Record<string, string | number | boolean> = {}) {
  const viz = await (runtime ??= instance());
  const ids = new Map(graph.nodes.map((n, i) => [n.id, `n${i}`]));
  const pairs = new Set<string>();
  const input = {
    directed: engine === 'dot', strict: true,
    graphAttributes: {overlap: 'prism', overlap_shrink: true, sep: `+${gap.nodeGapX / 2},${gap.nodeGapY / 2}`, pack: gap.groupGap,
      packmode: 'graph', start: '42', splines: 'false', outputorder: 'nodesfirst', K: 1.2, maxiter: 500,
      rankdir: 'TB', nodesep: gap.nodeGapX / 72, ranksep: gap.hierarchyRankGap / 72, ...attributes},
    nodeAttributes: {shape: 'box', label: '', fixedsize: true, margin: 0},
    nodes: graph.nodes.map(node => {
      const size = graphNodeSize(node);
      return {name: ids.get(node.id)!, attributes: {width: size.width / 72, height: size.height / 72}};
    }),
    edges: graph.edges.flatMap(edge => {
      const tail = ids.get(edge.source), head = ids.get(edge.target);
      if (!tail || !head || tail === head) return [];
      const key = engine === 'dot' || tail < head ? `${tail}:${head}` : `${head}:${tail}`;
      if (pairs.has(key)) return [];
      pairs.add(key);
      return [{tail, head}];
    }),
  };
  const result = JSON.parse(viz.renderString(input, {engine, format: 'json0', yInvert: true})) as {objects?: Array<{name: string; pos?: string}>};
  const positions = new Map<string, PointerPosition>();
  for (const node of result.objects ?? []) {
    const index = Number(node.name.slice(1));
    const [x, y] = (node.pos ?? '').split(',').map(Number);
    if (graph.nodes[index] && Number.isFinite(x) && Number.isFinite(y)) positions.set(graph.nodes[index].id, {x, y});
  }
  if (positions.size !== graph.nodes.length) throw new Error('Layout returned incomplete node coordinates.');
  return {positions, bends: new Map<string, number>()};
}
